/// <summary>
/// A dual-count line needing a decision, for the supervisor only: this is the one place expected and counted are side by side.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountVarianceSummaryLine
{
    real lineNumber;
    str itemNumber;
    str itemName;
    str locationId;
    str batchId;
    str serialId;
    str configId;
    str sizeId;
    str colorId;
    str styleId;
    str status;
    real systemQty;
    boolean needsApproval;
    List attempts;
}

Method.Source:
